WITH flagged AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM payments), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, amount, paid_at, status, is_new_session FROM islands ORDER BY paid_at NULLS LAST, amount DESC
